<CODE>
import { Injectable, BadRequestException } from '@nestjs/common';
import * as unzipper from 'unzipper';
import * as stream from 'stream';
import * as util from 'util';

@Injectable()
export class AppService {
  async convertZipToText(buffer: Buffer): Promise<string> {
    const pipeline = util.promisify(stream.pipeline);
    const zipStream = stream.Readable.from(buffer);
    const textContents: string[] = [];

    try {
      await pipeline(
        zipStream,
        unzipper.Parse(),
        async (entry) => {
          const fileName = entry.path;
          if (fileName.endsWith('.txt')) {
            const content = await entry.buffer();
            textContents.push(content.toString());
          } else {
            entry.autodrain();
          }
        }
      );
    } catch (error) {
      throw new BadRequestException('Error processing zip file');
    }

    return textContents.join('\n');
  }
}
</CODE>

<FILEPATH>
src/main.ts
</FILEPATH>
<CODE>
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(5000, '0.0.0.0');
}
bootstrap();
</CODE>

### Key Improvements:
1. **File Validation**: The controller now checks if the uploaded file is a zip file by verifying its MIME type.
2. **Error Handling**: The service method `convertZipToText` includes a try-catch block to handle errors during the zip file processing.
3. **Security**: The solution ensures that only `.txt` files are processed, and other files are ignored using `entry.autodrain()`.

This implementation ensures that the application is more robust and secure while maintaining the required functionality. You can start the application using `npm run start`, and it will listen on `0.0.0.0:5000`.

